import { convertFileSrc, invoke } from "@tauri-apps/api/core";
import { listen } from "@tauri-apps/api/event";
import { useSyncExternalStore } from "react";

/**
 * Cached pictures of one photo (generated by the backend's `preview` module):
 * a ~2560 px preview for review, a ~360 px thumbnail for strips and grids, the
 * original's upright size, and the share of clipped pixels.
 */
export interface PreviewInfo {
  hash: string;
  thumb: string;
  preview: string;
  width: number;
  height: number;
  overPct: number;
  underPct: number;
}

/** A photo to preview: identity hash + the JPG to decode. */
export interface PreviewRequest {
  hash: string;
  path: string;
}

interface PreviewResult {
  hash: string;
  info?: PreviewInfo | null;
  error?: string | null;
}

// Module-level store: previews arrive steadily while the background warm runs,
// and only the components showing a given photo should re-render.
const infos = new Map<string, PreviewInfo>();
const errors = new Map<string, string>();
const inflight = new Set<string>();
const listeners = new Set<() => void>();
let version = 0;

function notify() {
  version++;
  listeners.forEach((l) => l());
}

function subscribe(listener: () => void) {
  listeners.add(listener);
  return () => listeners.delete(listener);
}

function store(results: PreviewResult[]) {
  for (const r of results) {
    inflight.delete(r.hash);
    if (r.info) infos.set(r.hash, r.info);
    else if (r.error) errors.set(r.hash, r.error);
  }
  notify();
}

/** The preview info for a photo, re-rendering when it becomes available. */
export function usePreview(hash: string | undefined): PreviewInfo | undefined {
  return useSyncExternalStore(subscribe, () => (hash ? infos.get(hash) : undefined));
}

/** Why a photo has no preview (decode failure), if it failed. */
export function usePreviewError(hash: string | undefined): string | undefined {
  return useSyncExternalStore(subscribe, () => (hash ? errors.get(hash) : undefined));
}

/** Changes whenever any preview arrives (for views that summarise many). */
export function usePreviewsVersion(): number {
  return useSyncExternalStore(subscribe, () => version);
}

export function getPreview(hash: string | undefined): PreviewInfo | undefined {
  return hash ? infos.get(hash) : undefined;
}

/**
 * Make sure these photos have previews, generating the missing ones now (in
 * parallel, ahead of the background warm). Already known ones cost nothing.
 */
export async function requestPreviews(reqs: PreviewRequest[]): Promise<void> {
  const missing = reqs.filter(
    (r) => !infos.has(r.hash) && !errors.has(r.hash) && !inflight.has(r.hash),
  );
  if (missing.length === 0) return;
  missing.forEach((r) => inflight.add(r.hash));
  try {
    store(await invoke<PreviewResult[]>("get_previews", { items: missing }));
  } catch (err) {
    missing.forEach((r) => inflight.delete(r.hash));
    console.error("Preview request failed:", err);
  }
}

let warmListener: Promise<unknown> | null = null;

/**
 * Generate previews for a whole scan in the background, in the order given
 * (start from where the review begins). A new call replaces the previous run.
 */
export async function warmPreviews(reqs: PreviewRequest[]): Promise<void> {
  warmListener ??= listen<PreviewResult>("preview://ready", (e) => store([e.payload]));
  await warmListener;
  const todo = reqs.filter((r) => !infos.has(r.hash) && !errors.has(r.hash));
  if (todo.length > 0) await invoke("warm_previews", { items: todo });
}

/** URL the webview can load a cached preview/thumbnail (or any allowed file) from. */
export function assetUrl(path: string): string {
  return convertFileSrc(path);
}

/** Exposure label from clipping, same thresholds as the old readout. */
export function exposureLabel(info: PreviewInfo): "ok" | "overexposed" | "underexposed" {
  if (info.overPct > 5) return "overexposed";
  if (info.underPct > 5) return "underexposed";
  return "ok";
}
